import { ROLES, ROLE_MAP } from './roles.js';
import { SOURCES } from './public-sources.js';
import { ENDINGS, FAMILIES } from './endings.js';
import { LEGACY_ENDINGS } from './legacy.js';
import { STAT_LABELS, MAX_TURNS, createRun, getEvent, applyChoice, advance, requestExit, requestBreak, canRequestBreak, validRun, jobTitle, bossLabel } from './engine.js';
import { cloud } from './cloud.js';
const $=s=>document.querySelector(s),main=$('#main'),dialog=$('#dialog');
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='hedo-life-v3', REPO='https://github.com/gn02335338/hedo-life';
const pad=n=>String(n).padStart(2,'0'),randomSeed=()=>`e4-${crypto.randomUUID().replaceAll('-','').slice(0,29)}`;
const PEOPLE={self:{name:'你',title:'今天的主角',initial:'我'},wing:{name:'Wing',title:'執行長',image:'./assets/wing.png'},spencer:{name:'Spencer',title:'董事長',image:'./assets/spencer.png'},rick:{name:'Rick',title:'技術資深經理',initial:'R'},hope:{name:'Hope',title:'HR長',initial:'H'},erich:{name:'Erich',title:'法務長',initial:'E'},jenjen:{name:'JenJen',title:'行政長',initial:'J'},sonny:{name:'Sonny',title:'MIS',initial:'S'},'exit-team':{name:'Erich · JenJen · Sonny',title:'法務／行政／MIS',initial:'3'}};
let run=null,unlocked=[],legacy=[],records={},screen='home',selectedRole='ai',candidate=null,rerolls=0,storageAvailable=true,toastTimer,audioContext,audioGain,soundOn=false,collectionFilter={role:'all',status:'all',query:'',limit:24};
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null'),v2=JSON.parse(localStorage.getItem('hedo-life-v2')||'null'),v1=JSON.parse(localStorage.getItem('hedo-life-v1')||'null');if(validRun(saved?.run))run=saved.run;unlocked=[...new Set([...(Array.isArray(saved?.unlocked)?saved.unlocked:[]),...(Array.isArray(v2?.unlocked)?v2.unlocked:[])])].filter(id=>ENDINGS.some(e=>e.id===id));records=saved?.records&&typeof saved.records==='object'&&!Array.isArray(saved.records)?saved.records:{};legacy=[...new Set([...(Array.isArray(saved?.legacy)?saved.legacy:[]),...(Array.isArray(v2?.legacy)?v2.legacy:[]),...(Array.isArray(v1?.unlocked)?v1.unlocked:[])])].filter(id=>LEGACY_ENDINGS.some(e=>e.id===id));}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(STORE,JSON.stringify({run,unlocked,legacy,records}));}catch{if(storageAvailable)toast('這個瀏覽器無法存檔，本局仍可繼續。');storageAvailable=false;}$('#collection-count').textContent=`${unlocked.length} / ${ENDINGS.length}`;}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function view(html,name,focus=true){screen=name;main.innerHTML=html;if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}
function schoolHTML(r){const ed=r.education;return ed?`${esc(ed.school)}<small>${esc(ed.department)} · ${esc(ed.degree||'')}</small>`:'履歷保密中';}
function avatar(id,extra=''){const p=PEOPLE[id]||PEOPLE.wing;return `<span class="avatar ${extra}">${p.image?`<img src="${p.image}" alt="${p.name} 卡通角色" loading="lazy">`:`<span>${p.initial}</span>`}</span>`;}
function home(focus=true){view(`<section class="home"><div class="hero"><div class="hero-copy"><span class="eyebrow pill">OFFICE LIFE, UNPREDICTABLE.</span><h1>你的前途，<br><span>隨機應變。</span></h1><p class="hero-desc">履歷靠骰子，未來靠選擇。<br>歡迎加入禾多。這一次，你能待到哪一天？</p><div class="hero-actions"><button class="primary" data-action="new">擲出我的人生 <span>↗</span></button><button class="text-button" data-action="${run?'continue':'about'}">${run?(run.completed?'回看上次人生':'繼續上班'):'入職前先看看'} <span>→</span></button></div><div class="hero-numbers"><div><b>09</b><span>應徵職缺</span></div><div><b>${ENDINGS.length}</b><span>未知結局</span></div><div><b>∞</b><span>意料之外</span></div></div></div><div class="hero-stage" aria-label="Wing 與董事長 Spencer 的遊戲角色"><span class="shape circle"></span><span class="shape ring"></span><span class="shape yellow"></span><div class="hero-person spencer"><img src="./assets/spencer.png" alt="Spencer 董事長卡通人物"><span>SPENCER <small>董事長</small></span></div><div class="hero-person wing"><img src="./assets/wing.png" alt="Wing 執行長卡通人物"><span>WING <small>執行長</small></span></div><div class="speech-bubble">「我們很重視人才。」<small>至於你算不算，明天再說。</small></div><div class="floating-dice" aria-hidden="true">⚄</div><span class="stage-note">FICTIONAL OFFICE UNIVERSE / V.03</span></div></div><div class="feature-strip"><div><span>01 / ROLL</span><h2>先骰履歷，再談理想。</h2><p>能力、學歷、薪水。命運把牌發好，你決定怎麼打。</p></div><div><span>02 / CHOOSE</span><h2>選項沒有標準答案。</h2><p>同一句話，換個時間說，可能完全不是同一回事。</p></div><div><span>03 / DISCOVER</span><h2>結局，留給你遇見。</h2><p>每一個問號背後，都是另一種禾多人生。</p></div></div><div class="community-banner"><div><span class="eyebrow">THE STORY IS STILL BEING WRITTEN.</span><h2>還有一段，大家都記得的故事？</h2><p>把漏掉的梗、記憶與遊戲建議，交給「史冊補完計畫」。</p></div><button class="secondary" data-action="feedback">我來補一頁 <span>↗</span></button></div></section>`,'home',focus);}
function roleScreen(focus=true){view(`<section class="page roles-page"><div class="page-heading"><span class="eyebrow">STEP 01 / THE POSITION</span><h1>這次，你想應徵什麼？</h1><p class="page-lead">公司有很多可能，你也有。先挑一個想試試的職位。</p></div><div class="role-grid">${ROLES.map(r=>`<button class="role-card ${r.id===selectedRole?'selected':''}" data-role="${r.id}" aria-pressed="${r.id===selectedRole}"><span class="role-top"><span class="role-symbol">${r.symbol}</span><span class="check">${r.id===selectedRole?'✓':'↗'}</span></span><h2>${r.name}</h2><p class="role-subtitle">${esc(r.subtitle)}</p><p>${esc(r.description)}</p></button>`).join('')}</div><div class="role-bottom"><p>已選擇 <b>${ROLE_MAP[selectedRole].name}</b><small>職缺說明是一種美好的想像。</small></p><button class="primary" data-action="roll">擲出我的履歷 <span>⚄</span></button></div></section>`,'roles',focus);}
function rollCandidate(fresh=false){if(fresh)rerolls=0;else rerolls++;candidate=createRun(selectedRole,randomSeed());rollScreen();}
function rollScreen(){const dice=['⚀','⚁','⚂','⚃','⚄','⚅'];view(`<section class="page roll-page"><div class="page-heading"><span class="eyebrow">STEP 02 / A LITTLE LUCK</span><h1>這張履歷，夠有前途吧？</h1><p class="page-lead">今天的你，由命運親自排版。報到後的你，再說。</p></div><div class="resume-card"><div class="resume-heading"><div><span class="eyebrow">CANDIDATE / ${ROLE_MAP[selectedRole].name}</span><h2>你的平行人生履歷</h2></div><span class="resume-stamp">READY<br>TO WORK</span></div><div class="dice-stats">${['skill','slack','lick'].map(k=>`<div class="dice-stat"><span>${STAT_LABELS[k]}</span><div class="dice-row" aria-label="骰子點數 ${(candidate.abilityDice?.[k]||[]).join('、')}">${(candidate.abilityDice?.[k]||[3,3,3]).map(d=>`<i>${dice[d-1]}</i>`).join('')}</div><b>${candidate.stats[k]}<small>/ 100</small></b></div>`).join('')}</div><div class="resume-details"><div><span>🎓 抽中的學歷</span><h3>${schoolHTML(candidate)}</h3></div><div><span>✦ 面試談好的月薪</span><h3 class="offer-salary">${candidate.offerPay||candidate.pay}<small>K / 月</small></h3></div></div><p class="resume-fine">學歷與薪資皆為遊戲隨機設定，並非你的真實資料。能力可以在故事裡成長。</p></div><div class="roll-actions"><button class="text-button" data-action="back-roles">← 換個職缺</button><button class="secondary" data-action="reroll" ${rerolls>=3?'disabled':''}>${rerolls>=3?'骰子今天下班了':`再擲一次 · 還有 ${3-rerolls} 次`} <span>↻</span></button><button class="primary" data-action="start">就這樣，報到吧 <span>↗</span></button></div></section>`,'roll');}
function stat(key,value){const danger=['boss','mood','energy','cash'].includes(key)&&value<=20;return `<div class="stat ${danger?'danger':''}"><div class="stat-top"><span>${STAT_LABELS[key]}</span><b>${value}</b></div><div class="stat-track" role="meter" aria-label="${STAT_LABELS[key]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><div class="stat-fill" style="width:${value}%"></div></div></div>`;}
const signed=n=>`${n>0?'+':''}${n}`;
const LUCK_LABELS={success:'⚄ 這次順利過關',setback:'⚄ 這次不太順',lucky:'⚄ 這次運氣站在你這邊',ordinary:'⚄ 行動判定：平常發揮'};
function deltaChips(delta={}){return Object.entries(STAT_LABELS).filter(([k])=>Number.isFinite(delta[k])&&delta[k]!==0).map(([k,label])=>`<span class="delta-chip ${delta[k]>0?'delta-up':'delta-down'}"><span>${label}</span><b>${signed(delta[k])}</b></span>`).join('');}
function outcomeHTML(h,compact=false){const chips=deltaChips(h.delta);return `<div class="outcome-ledger ${compact?'compact':''}">${h.eventOutcome?`<p class="luck-result">⚄ ${esc(h.eventOutcome.label)}：${esc(h.eventOutcome.result)}</p>`:''}${h.chanceOutcome?`<p class="luck-result">${LUCK_LABELS[h.chanceOutcome]||'⚄ 命運已揭曉'}</p>`:''}<span class="ledger-label">這次實際變化</span><div class="delta-list" aria-label="事件後數值變化">${chips||'<span class="delta-neutral">數值沒有改變。</span>'}</div>${h.breakdown?.length?`<details class="effect-details"><summary>看看變化從哪裡來</summary><ul>${h.breakdown.map(part=>`<li><span>${esc(part.label)}</span><div class="delta-list">${deltaChips(part.delta)||'<span class="delta-neutral">已達數值上下限，沒有額外變化。</span>'}</div></li>`).join('')}</ul><p>上方是整件事的合計；數值介於 0～100，達到上限或下限後不再增減。</p></details>`:''}</div>`;}
function sourceLine(ids){const src=(ids||[]).map(id=>SOURCES[id]).filter(Boolean);return src.length?src.map(s=>s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)).join(' · '):'原創職場平行宇宙';}
function speakerFor(event){if(event.speaker&&PEOPLE[event.speaker])return event.speaker;return 'wing';}
function visibleChoices(){return getEvent(run).choices.map((c,i)=>({c,i})).filter(({c})=>c.available!==false);}
function game(focus=true){if(!run)return roleScreen();if(run.completed)return endingScreen();const current=getEvent(run),last=run.history.at(-1),ev=run.pending&&last?.eventId===current.id?{...current,title:last.title,body:last.body}:current,crisis=ev.kind==='crisis',person=speakerFor(ev),p=PEOPLE[person],choices=visibleChoices();view(`<section class="game-layout"><aside class="game-sidebar"><div class="player-card"><div class="employee-line"><span class="eyebrow">MY WORK ID</span><span class="level">LV.${run.rank}</span></div><h2>${esc(jobTitle(run))}</h2><p class="job-origin">應徵：${ROLE_MAP[run.roleId].name}${run.assignment!=='honest'?` <span class="job-warning">${run.assignment==='assistant'?'實際職務':'職務異動'}</span>`:''}</p><div class="salary-line"><span>遊戲月薪</span><b>${run.pay}<small>K</small></b></div><div class="education-mini">${schoolHTML(run)}</div></div><div class="boss-panel ${run.stats.boss<=20?'angry':''}"><div class="boss-intro">${avatar('wing')}<div><b>Wing</b><small>${bossLabel(run.stats.boss)}</small></div><span class="mood-dot"></span></div><div class="mood-stats">${stat('boss',run.stats.boss)}${stat('mood',run.stats.mood)}</div></div><div class="resource-stats">${['energy','cash','trust','dream'].map(k=>stat(k,run.stats[k])).join('')}</div><div class="skill-stats">${['skill','slack','lick'].map(k=>stat(k,run.stats[k])).join('')}</div>${run.pip?.active?`<div class="pip-status"><span>Hope 的改善計畫</span><b>剩 ${run.pip.remaining} 回合</b></div>`:''}<div class="sidebar-controls"><button data-action="guide">數值與運氣怎麼算？ ↗</button>${/^e[234]-/.test(run.seed)?`<button data-action="break" ${canRequestBreak(run)?'':'disabled'} title="一般工作事件中，每個工作回合可紓壓一次。先看完目前結果或通知。">花錢喘口氣 ↗</button>`:''}<button data-action="journal">背鍋紀錄 ↗</button><button data-action="exit" ${run.pending||ev.kind==='self-care'?'disabled':''}>我想離職了 ↗</button></div></aside><article class="chapter ${crisis?'crisis-chapter':''}">${!/^e[234]-/.test(run.seed)?'<div class="rules-notice"><p>這局保留原本的玩法。新版心情消耗、花錢紓壓與更多史冊事件，從新人生開始。</p><button class="text-button" data-action="new">開一段新人生 ↗</button></div>':''}<div class="chapter-meta"><span>${crisis?'SOMETHING HAPPENED':`DAY ${pad(Math.min(run.turn+1,MAX_TURNS))} / ${esc(ev.era||'上班日常')}`}</span><span class="tag">${ev.kind==='self-care'?'喘口氣':ev.kind==='onboarding'?'報到日':ev.kind==='fantasy'?'平行未來':crisis?'臨時通知':'禾多日常'}</span></div><div class="chapter-progress"><span style="width:${Math.min(100,(run.turn+1)/MAX_TURNS*100)}%"></span></div><h1 class="chapter-title">${esc(ev.title)}</h1><p class="chapter-body">${esc(ev.body)}</p>${ev.wing?`<div class="character-quote">${avatar(person,'quote-avatar')}<div><span class="speaker-name">${p.name} <small>${p.title} · 遊戲角色</small></span><p>${esc(ev.wing)}</p></div></div>`:''}${run.pending?`<div class="consequence" role="status"><span class="eyebrow">AND THEN… / 結果是這樣的</span><p class="result-text">${esc(last.result)}</p>${last.weather?`<p class="weather-note">☁ ${esc(last.weather.text)}</p>`:''}${outcomeHTML(last)}<div class="result-footer"><span>故事已記入這次人生</span><button class="primary" data-action="next">繼續 <span>→</span></button></div></div>`:`<div class="choices-label"><span>如果是你，會怎麼做？</span><small>不用猜標準答案。</small></div><div class="choices">${choices.map(({c,i},n)=>`<button class="choice" data-choice="${i}"><span class="choice-key">${pad(n+1)}</span><span class="choice-text">${esc(c.text)}</span><span class="choice-arrow">↗</span></button>`).join('')}</div>`}<p class="story-source">創作靈感 / ${sourceLine(ev.sourceIds)}</p></article></section>`,'game',focus);if(run.pending&&focus)$('.consequence').scrollIntoView({block:'nearest',behavior:'instant'});}
const types={good:'GOOD END',bad:'BAD END',normal:'ANOTHER LIFE',secret:'HIDDEN CHAPTER'};
function finishRecord(){if(run?.completed){if(!unlocked.includes(run.endingId)){unlocked.push(run.endingId);records[run.endingId]={turn:run.turn+1,job:jobTitle(run),pay:run.pay};toast(`一個問號，有了答案。${unlocked.length} / ${ENDINGS.length}`);}void cloud.complete(run);}save();}
function endingScreen(){const e=ENDINGS.find(e=>e.id===run?.endingId);if(!e)return home();view(`<section class="ending-page"><div class="ending-paper ${e.type==='bad'?'bad-ending':''}"><div class="ending-top"><span>THE HEDO LIFE / ${String(ENDINGS.indexOf(e)+1).padStart(3,'0')}</span><span>已解鎖 ✓</span></div><div class="ending-layout"><div><span class="ending-type">${types[e.type]}</span><h1>${esc(e.title)}</h1><p class="ending-subtitle">${esc(e.subtitle)}</p><p class="ending-body">${esc(e.body)}</p></div><div class="ending-symbol" aria-hidden="true"><span>${esc(e.symbol||'終')}</span><small>YOUR STORY.<br>YOUR ENDING.</small></div></div><div class="ending-employment"><span>應徵 <b>${ROLE_MAP[run.roleId].name}</b></span><span>實際 <b>${esc(jobTitle(run))}</b></span><span>存活 <b>${Math.min(run.turn+1,MAX_TURNS)} 回合</b></span><span>遊戲月薪 <b>${run.pay}K</b></span></div><div class="ending-stats">${Object.entries(STAT_LABELS).map(([k,v])=>`<div><b>${run.stats[k]}</b><span>${v}</span></div>`).join('')}</div></div><div class="ending-actions"><button class="primary" data-action="new">再活一次 <span>↻</span></button><button class="secondary" data-action="collection">翻開命運圖鑑 <span>↗</span></button><button class="text-button" data-action="download">下載離場證明 ↓</button></div><p class="ending-note">每一種離開，都不必等到最後。你的下一次人生，還有 ${ENDINGS.length-unlocked.length} 個問號。</p><details class="review-run"><summary>回看這次人生的背鍋紀錄</summary>${journalHTML()}</details></section>`,'ending');}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function collection(){collectionFilter={role:'all',status:'all',query:'',limit:24};openDialog(`<h2 id="dialog-title">還沒遇見的，都先保密。</h2><p class="dialog-lead">${unlocked.length} / ${ENDINGS.length} 個問號已有答案。剩下的，留給下一次選擇。</p><div class="collection-controls"><label for="filter-role">應徵職業<select id="filter-role"><option value="all">全部職業</option>${ROLES.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></label><label for="filter-status">收藏狀態<select id="filter-status"><option value="all">全部</option><option value="unlocked">已收藏</option><option value="locked">未解鎖</option></select></label><label for="filter-query">搜尋已收藏的故事<input id="filter-query" type="search" placeholder="只搜尋你已解鎖的結局"></label></div><p id="collection-summary" class="collection-summary"></p><div class="collection-grid" id="ending-grid"></div><button class="load-more secondary" data-action="more-endings">再翻一頁 ↓</button>${legacy.length?`<details class="review-run"><summary>第一版收藏（${legacy.length}）</summary><div class="collection-grid">${LEGACY_ENDINGS.filter(e=>legacy.includes(e.id)).map(e=>`<article class="ending-card unlocked"><span class="number">FIRST EDITION</span><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p></article>`).join('')}</div></details>`:''}`);renderCollection();}
function renderCollection(){const f=collectionFilter,list=ENDINGS.filter(e=>(f.role==='all'||e.roleId===f.role)&&(f.status==='all'||(f.status==='unlocked')===unlocked.includes(e.id))&&(!f.query||(unlocked.includes(e.id)&&[e.title,e.body,e.subtitle].join(' ').toLowerCase().includes(f.query.toLowerCase()))));$('#collection-summary').textContent=`${list.length} 張卡片 · 顯示 ${Math.min(f.limit,list.length)} 張`;$('#ending-grid').innerHTML=list.slice(0,f.limit).map(e=>{const yes=unlocked.includes(e.id);return yes?`<article class="ending-card unlocked"><div class="card-top"><span class="number">${String(ENDINGS.indexOf(e)+1).padStart(3,'0')} / ${ROLE_MAP[e.roleId].name}</span><span>✓</span></div><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p></article>`:`<article class="ending-card locked" aria-label="未解鎖結局"><span class="unknown-number">${String(ENDINGS.indexOf(e)+1).padStart(3,'0')}</span><span class="question-mark" aria-hidden="true">?</span><p>未完待續</p></article>`;}).join('')||'<p class="empty-state">你的已收藏故事裡，還沒有這個關鍵字。</p>';$('.load-more').hidden=f.limit>=list.length;}
function journalHTML(){if(!run?.history.length)return'<p class="dialog-lead">你的背鍋紀錄，目前還是乾淨的。</p>';return`<ol class="journal-list">${run.history.map((h,i)=>`<li><span class="eyebrow">${pad(i+1)} / DAY ${h.turn+1}</span><h3>${esc(h.title)}</h3><p class="journal-choice">${esc(h.choiceText)}</p><p>${esc(h.result)}</p>${h.weather?`<p class="weather-note">☁ ${esc(h.weather.text)}</p>`:''}${outcomeHTML(h,true)}<small>${esc(h.jobTitle)} · 遊戲月薪 ${h.pay}K</small></li>`).join('')}</ol>`;}
function about(){openDialog(`<h2 id="dialog-title">生存指南，不附解答。</h2><p class="dialog-lead">先選職缺，再骰履歷。工作、偷懶、舔功各有用途；有些事看能力，有些事真的要看運氣。</p><div class="rule-grid"><div><span>01</span><h3>先選擇，再揭曉</h3><p>相似的選擇也可能遇到不同結果。選完才會顯示實際數值增減與這次的運氣。</p></div><div><span>02</span><h3>上班會消耗心情</h3><p>注意自己，也留意老闆的臉色。需要時花錢喘口氣，別把所有薪水都留給下一個工作回合。</p></div><div><span>03</span><h3>隨時可以離開</h3><p>工作證上有離職按鈕。留下或離開，都可以是一段完整的故事。</p></div><div><span>04</span><h3>問號留給自己解開</h3><p>最多24個工作回合。每一步自動存檔，解鎖的故事收進你的命運圖鑑。</p></div></div><p class="dialog-lead">學歷、薪水與人物偏見均是虛構遊戲設定；不同學校與科系不代表能力高低。老闆的偏見，是他的問題。</p>`);}
function statGuide(){openDialog(`<h2 id="dialog-title">上班靠什麼，運氣算哪裡。</h2><p class="dialog-lead">選擇前不揭曉數值與判定。選擇後可看實際增減、運氣結果與變化明細；背鍋紀錄也會保留。</p><div class="guide-table"><table><caption>每個數值都有用途</caption><thead><tr><th scope="col">數值</th><th scope="col">會影響什麼</th></tr></thead><tbody><tr><th scope="row">老闆心情</th><td>人事危機、協商與升遷的判定，也會受當天隨機脾氣影響。PIP 不會自動讓他開心。</td></tr><tr><th scope="row">自己心情</th><td>每次工作會消耗，低落時出現情緒危機。PIP、低體力與砍薪後的壓力會讓上班更難熬。</td></tr><tr><th scope="row">體力</th><td>做事與救火的本錢，耗盡會結束這段人生，也關係到後期能否走下去。</td></tr><tr><th scope="row">存款</th><td>0～100 的遊戲資源點數，並非新臺幣。可以花來紓壓，耗盡也會離場；遊戲月薪決定定期入帳多少。</td></tr><tr><th scope="row">同事情義</th><td>累積合作與互助的成果，影響部分後期路線能否成立。</td></tr><tr><th scope="row">大餅信仰</th><td>你還願意相信願景多少，影響部分後期路線。高低都可以是自己的選擇。</td></tr><tr><th scope="row">工作能力</th><td>協商、PIP 答辯、升遷及做事遇到好結果的機會；能力高也不保證成功。</td></tr><tr><th scope="row">偷懶能力</th><td>提高省電時遇到好運的機會，降低一般工作事件的倒楣機會，並影響職涯選擇。</td></tr><tr><th scope="row">舔老闆能力</th><td>討好型協商、升遷與相關選擇的成功機會，也影響職涯選擇。</td></tr></tbody></table></div><div class="rule-grid"><div><span>⚄ / 入職</span><h3>每一局，重新發牌</h3><p>能力骰子、學歷與科系、薪資、職務改派都有亂數。空降主管保留原職。</p></div><div><span>⚄ / 工作</span><h3>同樣的選擇，也有變數</h3><p>日常事件會抽取；選擇後會判定幸運、平常或不順，並抽出老闆當天的脾氣。部分事件另有劇情抽籤，結果會在事後顯示。</p></div><div><span>⚄ / 人事</span><h3>能力影響機會</h3><p>協商、PIP 答辯及升遷會判定成敗；學歷閒聊、砍薪時機與幅度也會隨機變動。</p></div><div><span>☕ / 紓壓</span><h3>薪水也可以花在自己身上</h3><p>一般工作事件中，每回合可花錢喘口氣一次。餐點、朋友與休息的療癒效果也有高低；錢不足時不會提供買不起的選項。</p></div></div>${run&&!/^e[234]-/.test(run.seed)?'<p class="small-note">你目前這局沿用舊版規則，以保留進度。新的心情消耗、PIP 調整與紓壓功能會從新局開始。</p>':''}`);}
function sources(){openDialog(`<h2 id="dialog-title">故事有靈感，人生有改編。</h2><p class="dialog-lead">本作是非官方職場諷刺遊戲。參考私人史冊的敘事與公開產品資料；角色台詞、因果、薪資與結局皆為創作，不是企業現況報告。</p><div class="sources-list">${Object.values(SOURCES).map((s,i)=>`<article class="source-item"><span class="number">${pad(i+1)}</span><div><h3>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</h3><p>${esc(s.summary||'私人史冊虛構敘事改編。')}</p></div></article>`).join('')}</div><p class="source-disclaimer">互動節奏參考 <a href="https://otherlife.icareu.tw/" target="_blank" rel="noopener noreferrer">地球轉生所</a> 與 <a href="https://1in8b.life/zh/" target="_blank" rel="noopener noreferrer">八十億分之一</a>；視覺色彩參考 <a href="https://www.avividai.com/" target="_blank" rel="noopener noreferrer">AviviD 官網</a>。未使用官方標誌或暗示官方製作。</p>`);}
function feedback(){const base=`${REPO}/issues/new?template=`;openDialog(`<h2 id="dialog-title">史冊補完計畫。</h2><p class="dialog-lead">那些「對啦，就是這樣」的瞬間，值得多寫一頁。挑一種投稿方式，在 GitHub 預覽後由你送出。</p><div class="feedback-grid"><a class="feedback-card" href="${base}memory.yml" target="_blank" rel="noopener noreferrer"><span>✎ / MEMORY</span><h3>補一頁史冊</h3><p>一段記得的職場橋段、一句經典台詞，或有趣的產品故事。</p><b>提供創作靈感 ↗</b></a><a class="feedback-card" href="${base}suggestion.yml" target="_blank" rel="noopener noreferrer"><span>✦ / IDEA</span><h3>讓人生更好玩</h3><p>新職業、新機制、結局構想，或你希望看到的下一個角色。</p><b>提出遊戲建議 ↗</b></a><a class="feedback-card" href="${base}bug.yml" target="_blank" rel="noopener noreferrer"><span>⌁ / BUG</span><h3>這次真的不是命</h3><p>卡關、按鈕失效、畫面異常。把問題交給我們。</p><b>回報遊戲問題 ↗</b></a></div><p class="small-note">GitHub Issues 是公開的。請用化名、去識別的摘要；不要貼私人聯絡方式、完整聊天紀錄或未遮蔽的內部文件。投稿不會自動成為遊戲內容。</p>`);}
function privacy(){const state=cloud.state;openDialog(`<h2 id="dialog-title">只記得你玩過的人生。</h2><p class="dialog-lead">不用註冊。這個瀏覽器會產生隨機匿名識別碼，讓你保留自己的結局收藏。</p><div class="privacy-card"><h3>${state.playerId?`匿名玩家 ${esc(state.playerId.slice(0,8))}`:'本機收藏模式'}</h3><p>目前：${state.status==='online'?'已連接人生觀測站':state.status==='pending'?'等待同步':'收藏仍保存在這個瀏覽器'}</p>${state.lastError?`<p class="sync-notice">${esc(state.lastError)}</p>`:''}<p>伺服器只保存匿名玩家、已驗證結局、遊戲職業、回合數、遊戲薪資與完成時間。未收集姓名、Email、真實學歷，也不保存原始選擇內容或 IP。</p><p>統計頁只顯示總數。清除瀏覽器資料後，無法靠姓名找回這個匿名身分；不同裝置會是不同玩家。</p><div class="privacy-actions"><button class="secondary" data-action="sync">重新連線 ↻</button><button class="text-button" data-action="export-collection">匯出圖鑑 ↓</button><label class="text-button import-label">匯入圖鑑 ↑<input id="import-collection" type="file" accept="application/json,.json" hidden></label></div><p>跨網址或裝置可用匯出／匯入帶走已收藏故事；匯入收藏不會灌入全站統計。</p></div>`);}
async function statistics(){openDialog(`<h2 id="dialog-title">人生觀測站。</h2><p class="dialog-lead">有人剛入職，有人已經下班。這裡只看總數，不劇透故事。</p><div id="stats-content" aria-live="polite"><p class="empty-state">正在整理大家的人生…</p></div>`);try{const data=await cloud.stats();if(!$('#stats-content'))return;const roles=ROLES.map(r=>({...r,count:Number(data.roles?.find(x=>x.id===r.id)?.count)||0})),max=Math.max(1,...roles.map(r=>r.count)),total=Number(data.totalRuns)||0,days=data.daily||[],dayMax=Math.max(1,...days.map(d=>Number(d.count)||0));$('#stats-content').innerHTML=`<div class="stat-tiles"><div><b>${Number(data.players)||0}</b><span>匿名玩家</span></div><div><b>${total}</b><span>已完成的人生</span></div><div><b>${Number(data.uniqueEndings)||0}<small> / ${ENDINGS.length}</small></b><span>大家遇見的結局</span></div><div><b>${Number(data.averageTurns||0).toFixed(1)}</b><span>平均存活回合</span></div></div>${!total?'<p class="empty-state">觀測站剛開門。第一份離場證明，等你寫下。</p>':''}<section class="chart-panel"><div class="chart-heading"><h3>大家從什麼職缺出發？</h3><span>已完成局數</span></div><div class="bar-chart" role="img" aria-label="${esc(roles.map(r=>`${r.name}：${r.count}局`).join('，'))}">${roles.map(r=>`<div class="bar-row"><span>${r.name}</span><div><i style="width:${r.count/max*100}%"></i></div><b>${r.count}</b></div>`).join('')}</div></section><section class="chart-panel"><div class="chart-heading"><h3>最近的人生動態</h3><span>每日完成局數 · UTC</span></div>${days.length?`<div class="daily-chart" role="img" aria-label="${esc(days.slice(-14).map(d=>`${d.date}：${d.count}局`).join('，'))}">${days.slice(-14).map(d=>`<div title="${esc(d.date)}：${Number(d.count)}局"><b>${Number(d.count)}</b><span style="height:${Math.max(3,Number(d.count)/dayMax*110)}px"></span><small>${esc(d.date.slice(5))}</small></div>`).join('')}</div>`:'<p class="empty-state">還沒有足夠的故事畫成曲線。</p>'}</section><p class="small-note">匿名遊玩統計，不是員工或企業現況調查。未解鎖的結局名稱，在這裡也不會出現。</p>`;}catch{if($('#stats-content'))$('#stats-content').innerHTML='<div class="empty-state"><h3>觀測站暫時休息。</h3><p>遊戲和本機圖鑑照常運作；連線恢復後會再同步。</p><button class="secondary" data-action="stats">重新整理 ↻</button></div>';}}
function downloadCard(){const e=ENDINGS.find(e=>e.id===run.endingId),lines=[],body=Array.from(e.body);while(body.length)lines.push(body.splice(0,23).join(''));const statBase=Math.max(810,320+lines.length*35+70),height=statBase+350;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="${height}" viewBox="0 0 900 ${height}"><rect width="900" height="${height}" fill="#fff7fa"/><circle cx="820" cy="80" r="180" fill="#fbdce8"/><rect x="35" y="35" width="830" height="${height-70}" rx="28" fill="none" stroke="#e6256e" stroke-width="2"/><g fill="#14192d" font-family="sans-serif"><text x="80" y="110" font-size="20" letter-spacing="3">THE HEDO LIFE / 禾多人生</text><text x="80" y="170" font-size="18" fill="#e6256e">${esc(types[e.type])}</text><text x="80" y="250" font-size="48" font-weight="700">${esc(e.title)}</text>${lines.map((l,i)=>`<text x="80" y="${330+i*35}" font-size="25">${esc(l)}</text>`).join('')}<text x="80" y="${statBase-35}" font-size="18">應徵 ${ROLE_MAP[run.roleId].name} → 實際 ${esc(jobTitle(run))}</text><line x1="80" y1="${statBase}" x2="820" y2="${statBase}" stroke="#e9bed0"/>${Object.entries(STAT_LABELS).map(([k,v],i)=>`<text x="${85+(i%3)*250}" y="${statBase+48+Math.floor(i/3)*55}" font-size="21">${v}　${run.stats[k]}</text>`).join('')}<text x="80" y="${height-105}" font-size="18">第${Math.min(run.turn+1,MAX_TURNS)}回合離場 · 遊戲月薪${run.pay}K</text><text x="80" y="${height-65}" font-size="13">非官方職場諷刺遊戲 · 人物對白與結局為虛構改編</text></g></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`禾多人生-${e.title}.svg`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('離場證明已下載。這份不用任何人簽名。');}
async function toggleSound(){try{if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioContext.createGain();audioGain.gain.value=0;audioGain.connect(audioContext.destination);[130.81,196,261.63,329.63].forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.12/(i+1);o.connect(g);g.connect(audioGain);o.start();});}await audioContext.resume();soundOn=!soundOn;audioGain.gain.setTargetAtTime(soundOn?.055:0,audioContext.currentTime,.3);$('.sound-button').setAttribute('aria-pressed',soundOn);$('.sound-button').setAttribute('aria-label',soundOn?'關閉背景音效':'開啟背景音效');$('#sound-label').textContent=soundOn?'聲音開':'聲音關';}catch{toast('目前無法播放音效。');}}
function choose(index){if(screen!=='game'||run.pending||dialog.open)return;const c=getEvent(run).choices[index];if(!c||c.available===false)return;run=applyChoice(run,index);save();game();}
function next(){run=advance(run);finishRecord();game();}
function newLife(){if(run&&!run.completed)openDialog(`<h2 id="dialog-title">重新擲一段人生？</h2><p class="dialog-lead">目前在第 ${run.turn+1} 回合。開始新局會取代這局進度；已收藏的故事都會保留。</p><div class="ending-actions"><button class="primary" data-action="confirm-new">選新職缺 →</button><button class="text-button" data-action="close-dialog">先保留這一局</button></div>`);else roleScreen();}
function readFilter(){collectionFilter.role=$('#filter-role').value;collectionFilter.status=$('#filter-status').value;collectionFilter.query=$('#filter-query').value.trim();collectionFilter.limit=24;renderCollection();}
let searchTimer;document.addEventListener('input',event=>{if(event.target.id==='filter-query'){clearTimeout(searchTimer);searchTimer=setTimeout(readFilter,120);}});document.addEventListener('change',event=>{if(event.target.id?.startsWith('filter-'))readFilter();});
document.addEventListener('click',async event=>{const rb=event.target.closest('[data-role]');if(rb){selectedRole=rb.dataset.role;roleScreen(false);$(`[data-role="${selectedRole}"]`).focus({preventScroll:true});return;}const cb=event.target.closest('[data-choice]');if(cb){choose(Number(cb.dataset.choice));return;}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='home')home();if(action==='new')newLife();if(action==='confirm-new'){dialog.close();roleScreen();}if(action==='roll')rollCandidate(true);if(action==='reroll'&&rerolls<3)rollCandidate();if(action==='back-roles')roleScreen();if(action==='start'&&candidate){run=structuredClone(candidate);run.runId=crypto.randomUUID();candidate=null;save();game();}if(action==='continue')game();if(action==='next')next();if(action==='exit'){run=requestExit(run);save();game();}if(action==='collection')collection();if(action==='more-endings'){collectionFilter.limit+=24;renderCollection();}if(action==='sources')sources();if(action==='about')about();if(action==='guide')statGuide();if(action==='break'){const nextRun=requestBreak(run);if(nextRun!==run){run=nextRun;save();game();}}if(action==='feedback')feedback();if(action==='privacy')privacy();if(action==='stats')void statistics();if(action==='sync'){await syncCloud();toast(cloud.state.status==='online'?'已連接觀測站。':'目前仍是本機模式，收藏都還在。');privacy();}if(action==='journal')openDialog(`<h2 id="dialog-title">這段人生，逐筆留存。</h2><p class="dialog-lead">回頭看才知道，每一次選擇把你帶到哪裡。</p>${journalHTML()}`);if(action==='close-dialog')dialog.close();if(action==='download')downloadCard();if(action==='sound')toggleSound();if(action==='export-collection')exportCollection();});
document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.repeat||dialog.open||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(screen==='game'&&!run.pending&&/^[1-9]$/.test(event.key)){const picked=visibleChoices()[Number(event.key)-1];if(picked){event.preventDefault();choose(picked.i);}}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
let lastSyncNotice='';cloud.subscribe(s=>{$('#cloud-status').textContent=s.status==='online'?'● 匿名紀錄已連線':s.status==='connecting'?'連接觀測站…':s.status==='pending'?`○ ${s.pending} 局待同步`:'○ 本機收藏模式';$('#cloud-status').title=s.lastError||'';if(s.lastError&&s.lastError!==lastSyncNotice){lastSyncNotice=s.lastError;toast(s.lastError);}});
async function syncCloud(){const data=await cloud.init();if(data&&run?.completed)void cloud.complete(run);if(data?.unlocked){unlocked=[...new Set([...unlocked,...data.unlocked.filter(id=>ENDINGS.some(e=>e.id===id))])];save();}}
function exportCollection(){const blob=new Blob([JSON.stringify({format:'hedo-collection',version:3,unlocked,legacy},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='禾多人生-我的圖鑑.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('圖鑑已匯出。不含匿名登入金鑰。');}
document.addEventListener('change',async event=>{if(event.target.id!=='import-collection')return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>100000)throw new Error();const data=JSON.parse(await file.text());if(data.format!=='hedo-collection'||!Array.isArray(data.unlocked))throw new Error();unlocked=[...new Set([...unlocked,...data.unlocked.filter(id=>ENDINGS.some(e=>e.id===id))])];legacy=[...new Set([...legacy,...(Array.isArray(data.legacy)?data.legacy:[]).filter(id=>LEGACY_ENDINGS.some(e=>e.id===id))])];save();toast('圖鑑已匯入此瀏覽器。');}catch{toast('這不是可辨識的禾多人生圖鑑檔案。');}event.target.value='';});
save();home(false);void syncCloud();
